steps.script:
@echo off
rem The DXVK tarball expands to dxvk-X.Y\x64\*.dll and dxvk-X.Y\x32\*.dll under
rem %LSW_EXTRACT_DIR%. capture_setup expects them one level higher
rem (C:\ProgramData\LSW\dxvk\x64\... and \x32\...), so flatten the versioned wrapper.
for /d %%D in ("%LSW_EXTRACT_DIR%\dxvk-*") do (
  xcopy /E /I /Y "%%D\*" "%LSW_EXTRACT_DIR%\" >nul
  rd /s /q "%%D"
)
exit /b 0

@echo off
rem VKD3D-Proton tarball expands to vkd3d-proton-X.Y\x64\*.dll and \x86\*.dll under
rem %LSW_EXTRACT_DIR%. capture_setup wants those one level up (\vkd3d\x64\ and \vkd3d\x86\).
rem .tar.zst extraction needs Win11 24H2+ (libarchive 3.6 with zstd in the in-box tar.exe).
for /d %%D in ("%LSW_EXTRACT_DIR%\vkd3d-proton-*") do (
  xcopy /E /I /Y "%%D\*" "%LSW_EXTRACT_DIR%\" >nul
  rd /s /q "%%D"
)
exit /b 0
